    addReplyProto(c, "-ERR ", 5);
    addReplyProto(c, "value is not an integer or out of range",
                  sizeof("value is not an integer or out of range")-1);
    addReplyProto(c, "\r\n", 2);
    afterErrorReply(c, "value is not an integer or out of range",
                    sizeof("value is not an integer or out of range")-1, 0);
    return;
}
if (bit_ll < LONG_MIN || bit_ll > LONG_MAX) {
    addReplyProto(c, "-ERR ", 5);
    addReplyProto(c, "value is out of range",
                  sizeof("value is out of range")-1);
    addReplyProto(c, "\r\n", 2);
    afterErrorReply(c, "value is out of range",
                    sizeof("value is out of range")-1, 0);
    return;
}
bit = (long) bit_ll;
if (bit != 0 && bit != 1) {
    addReplyProto(c, "-ERR ", 5);
    addReplyProto(c, "The bit argument must be 1 or 0.",
